const params = tobub.params;
const adapter = tobub.adapter;
const utils = tobub.utils;

const times = params.times;
const minComments = params.comments;
const maxNoNewData = 5;

await adapter.bootstrap();
// if (!await adapter.isLogin()) throw new Error('Platform login state is invalid');
await adapter.navigateTo({ name: 'home' });

let noNewDataCount = 0;
let totalNew = 0;

for (let i = 0; i < times; i++) {
  await tobub.reporter.emit({
    source: 'skill',
    action: 'feed.scroll',
    phase: 'progress',
    severity: 'info',
    payload: { iteration: i + 1 }
  });

  if(utils.chance(1/400)){
    await tobub.atoms.waitFor({ delay: [30000, 60000] });
  }

  await tobub.atoms.scroll({
    direction: 'down',
    distance:  utils.randInt(350, 900),
    mode: 'mouse',
    steps: 8,
    containerSelector: await adapter.getSelector('feedContainer'),
    stepPauseRange: [15, 30],
    pauseRange: [500, 1500]
  });

  await tobub.atoms.waitFor({ delay: [3000, 10000] });

  if(utils.chance(1/15)){
    await tobub.atoms.waitFor({ delay: [5000, 10000] });
  }

  const result = await adapter.extractData('list_extractor');
  const currentNew = [];

  for (const record of result.records ?? []) {
    const comments = Number.parseInt(String(record.fields?.comments ?? '0').replace(/[^\d]/g, ''), 10) || 0;
    if (comments < minComments || !record.id) continue;

    const saved = await tobub.db.saveContent({
      contentType: 'article',
      externalId: record.id,
      title: record.fields?.title ?? '',
      summary: record.fields?.author ?? '',
      url: `https://www.toutiao.com/article/${record.id}/`,
      metadata: { comments },
      rawData: record.fields ?? {}
    });

    if (saved.isNew) currentNew.push({ record, saved });
  }

  totalNew += currentNew.length;
  if (currentNew.length > 0 && utils.chance(9/10)) {
    const target = currentNew[utils.randInt(0, currentNew.length - 1)];
    let page;
    console.log(target.saved);
    try {
      page = await adapter.openPage('article2', { id: target.record.id });

      const detailTimes = utils.randInt(2, 4);
      for (let index = 0; index < detailTimes; index++) {
        await adapter.executeAtoms(page, [
          { atom: 'scroll', options: { direction: 'down', distance: [200, 500], steps: 8 } },
          { atom: 'waitFor', options: { delay: [3000, 5000] } }
        ]);
      }

      const commentArea = await adapter.getSelector('commentArea');

      await adapter.executeAtoms(page, [{
        atom: 'evaluate',
        options: {
          expression: '(selector) => document.querySelector(selector)?.scrollIntoView()',
          arg: Array.isArray(commentArea) ? commentArea[0] : commentArea,
          mode: 'function'
        }
      }]);

      const comments = await adapter.extractPageData(page, 'comment_extractor');
      const commentList = (comments.records ?? [])
        .map((item, index) => `${index + 1}.${item.fields?.name ?? ''}说:${item.fields?.content ?? ''}`)
        .join(';') + ';';

      let aiResult = {};
      // const aiResult = await tobub.ai.sse('generateText', {
      //   chat_id: 990003,
      //   contents: [{
      //     type: 'form',
      //     text: {
      //       scene: 'comment',
      //       title: target.record.fields?.title ?? '',
      //       commentList
      //     }
      //   }],
      //   params: {
      //     stream: true,
      //     ext: { contract_id: '2068740752307085313' }
      //   },
      //   response_format: { type: 'text' }
      // });

      await tobub.reporter.emit({
        source: 'skill',
        action: 'comment.generate',
        phase: 'succeeded',
        severity: 'info',
        payload: { commentCount: comments.records?.length ?? 0, answer: aiResult?.data ?? ''}
      });

      await tobub.db.recordAction({
        actionTypeCode: 'comment',
        contentDataId: target.saved.contentDataId,
        contentId:target.saved.contentId
      });
      await tobub.atoms.waitFor({ delay: [3000, 15000] });
    } catch (error) {
      await tobub.reporter.emit({
        source: 'skill',
        action: 'detail.flow',
        phase: 'failed',
        severity: 'error',
        error: { code: 'detail_flow_failed', message: error instanceof Error ? error.message : String(error) }
      });
    } finally {
      if (page) await adapter.closePage(page);
    }
  }

  noNewDataCount = currentNew.length === 0 ? noNewDataCount + 1 : 0;
  if (noNewDataCount >= maxNoNewData) break;
}

return { times, totalNew, noNewDataCount };
